        char = s[index]
        if char == '"':
            return parse_string(index)
        elif char.isdigit() or char == '-':
            return parse_number(index)
        elif s.startswith("true", index):
            return True, index + 4
        elif s.startswith("false", index):
            return False, index + 5
        elif s.startswith("null", index):
            return None, index + 4
        elif char == '[':
            return parse_array(index)
        elif char == '{':
            return parse_object(index)
        raise ValueError(f"Unexpected character {char} at index {index}")

    def parse_string(index):
        index += 1  # skip opening quote
        start = index
        while index < len(s):
            if s[index] == '"':
                return s[start:index], index + 1
            elif s[index] == '\\':
                index += 2  # skip escape character and next char
            else:
                index += 1
        raise ValueError("Unterminated string")

    def parse_number(index):
        start = index
        if s[index] == '-':
            index += 1
        while index < len(s) and (s[index].isdigit() or s[index] == '.'):
            index += 1
