            if s[index] == ']':
                return arr, index + 1
            elif s[index] != ',':
                raise ValueError("Expected ',' or ']' in array")
            index += 1  # skip comma
        raise ValueError("Unterminated array")

    def parse_object(index):
        index += 1  # skip opening brace
        obj = {}
        while index < len(s):
            index = skip_whitespace(index)
            if s[index] == '}':
                return obj, index + 1
            key, index = parse_string(index)
