                return obj, index + 1
            elif s[index] != ',':
                raise ValueError("Expected ',' or '}' in object")
            index += 1  # skip comma
        raise ValueError("Unterminated object")

    def skip_whitespace(index):
        while index < len(s) and s[index].isspace():
            index += 1
        return index

    result, next_index = parse_value(skip_whitespace(0))
    if next_index != len(s):
        raise ValueError("Extra data after JSON value")
    return result

