    """
    A state machine based parser for JSON strings. This function 
    processes characters iteratively and uses states to track 
    the parsing of strings, numbers, booleans, null, arrays, 
    and objects.
    """

    def parse():
        nonlocal index
        while index < len(s):
            if s[index].isspace():
                index += 1
                continue

            if s[index] == '"':
                return parse_string()
            elif s[index] == '{':
                return parse_object()
            elif s[index] == '[':
