                return None
            elif s[index].isdigit() or s[index] == '-':
                return parse_number()
            else:
                raise ValueError(f"Unexpected character {s[index]} at index {index}")

    def parse_string():
        nonlocal index
        index += 1  # skip opening quote
        str_start = index
        while index < len(s):
            if s[index] == '"':
                result = s[str_start:index]
                index += 1  # skip closing quote
                return result
            elif s[index] == '\\':
                index += 1  # skip escape character
            index += 1

        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        num_start = index
        if s[index] == '-':
            index += 1
        while index < len(s) and (s[index].isdigit() or s[index] == '.'):
            index += 1

        number_str = s[num_start:index]
        if '.' in number_str:
            return float(number_str)
        return int(number_str)

    def parse_array():
        nonlocal index
        index += 1  # skip opening bracket
        arr = []
        while index < len(s):
            if s[index].isspace():
                index += 1
                continue
            if s[index] == ']':
                index += 1  # skip closing bracket
                return arr

            arr.append(parse())
            while index < len(s) and s[index].isspace():
                index += 1

            if s[index] == ',':
                index += 1  # skip comma
            elif s[index] == ']':
                index += 1  # skip closing bracket
                return arr
            else:
                raise ValueError("Expected ',' or ']' in array")

    def parse_object():
        nonlocal index
        index += 1  # skip opening brace
        obj = {}
        while index < len(s):
            if s[index].isspace():
                index += 1
                continue
            if s[index] == '}':
                index += 1  # skip closing brace
                return obj

            key = parse_string()
            while index < len(s) and s[index].isspace():
                index += 1

            if s[index] != ':':
                raise ValueError("Expected ':' after object key")
            index += 1  # skip colon

            obj[key] = parse()
            while index < len(s) and s[index].isspace():
                index += 1

            if s[index] == ',':
                index += 1  # skip comma
            elif s[index] == '}':
                index += 1  # skip closing brace
                return obj
            else:
                raise ValueError("Expected ',' or '}' in object")

    index = 0
    result = parse()
    while index < len(s) and s[index].isspace():
        index += 1
    if index != len(s):
        raise ValueError("Extra data after JSON value")

    return result

def parse_json(s: str) -> object:
    """
    A token-based parser that reads the JSON string and builds 
    the resulting data structures incrementally. It uses a finite 
    state machine approach to move through tokens defined by JSON 
    syntax, handling strings, numbers, booleans, null, arrays, 
    and objects.
    """

    def next_token():
        nonlocal position
        while position < len(s) and s[position].isspace():
            position += 1

        if position >= len(s):
            return None

        char = s[position]

        if char == '"':
            return parse_string()
        elif char == '{':
            position += 1
            return '{'
        elif char == '}':
            position += 1
            return '}'
        elif char == '[':
            position += 1
            return '['
        elif char == ']':
            position += 1
            return ']'
        elif char == ',':
            position += 1
            return ','
        elif char == ':':
            position += 1
            return ':'
        elif char.isdigit() or char == '-':
            return parse_number()
        elif s.startswith("true", position):
            position += 4
            return True
        elif s.startswith("false", position):
            position += 5
            return False
        elif s.startswith("null", position):
            position += 4
            return None
        else:
            raise ValueError(f"Unexpected character at position {position}")

    def parse_string():
        nonlocal position
        position += 1  # skip opening quote
        start = position
        while position < len(s):
            char = s[position]
            if char == '"':
                result = s[start:position]
                position += 1  # skip closing quote
                return result
            elif char == '\\':
                position += 1  # skip escape character
            position += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal position
        start = position
        if s[position] == '-':
            position += 1
        while position < len(s) and (s[position].isdigit() or s[position] == '.'):
            position += 1
        number_str = s[start:position]
        return float(number_str) if '.' in number_str else int(number_str)

    def parse_array():
        arr = []
        while True:
            token = next_token()
            if token is None:
                raise ValueError("Unexpected end of input while parsing array")
            elif token == ']':
                break
            else:
                arr.append(token)
                token = next_token()
                if token and token != ',':
                    raise ValueError("Expected ',' or ']' in array")
        return arr

    def parse_object():
        obj = {}
        while True:
            token = next_token()
            if token is None:
                raise ValueError("Unexpected end of input while parsing object")
            elif token == '}':
                break
            elif not isinstance(token, str):
                raise ValueError("Expected string for object key")
            key = token
            if next_token() != ':':
                raise ValueError("Expected ':' after object key")
            obj[key] = next_token()
            token = next_token()
            if token and token != ',':
                raise ValueError("Expected ',' or '}' in object")
        return obj

    position = 0
    result = next_token()
    if result is None or position < len(s):
        raise ValueError("Extra data after JSON value")
    return result

