    """
    A stack-based parser that uses a list as a stack to handle 
    nested structures in JSON. It processes characters one by one, 
    building up the data structure incrementally while maintaining
    context on nested objects and arrays.
    """

    stack = []
    current_value = None
    state = 'init'  # Possible states: 'init', 'string', 'number', 'object_key', 'object_value', 'array'
    index = 0

    def pop_value():
        nonlocal current_value, stack
        if current_value is not None:
            stack.append(current_value)
            current_value = None

    while index < len(s):
        char = s[index]

        if char.isspace():
            index += 1
            continue

        if state == 'init':
            if char == '"':
                state = 'string'
                str_start = index + 1
            elif char == '{':
                stack.append({})
                state = 'object_key'
            elif char == '[':
                stack.append([])
                state = 'init'
            elif char == 't' and s.startswith("true", index):
                current_value = True
                index += 4
            elif char == 'f' and s.startswith("false", index):
                current_value = False
                index += 5
            elif char == 'n' and s.startswith("null", index):
                current_value = None
                index += 4
            elif char.isdigit() or char == '-':
                num_start = index
                while index < len(s) and (s[index].isdigit() or s[index] == '.'):
                    index += 1
                num_str = s[num_start:index]
                current_value = float(num_str) if '.' in num_str else int(num_str)
            else:
                raise ValueError(f"Unexpected character {char} at index {index}")

        elif state == 'string':
            if char == '"':
                current_value = s[str_start:index]
                index += 1
                state = 'init'
            elif char == '\\':
                index += 2  # Skip escaped character
            else:
                index += 1

        elif state == 'object_key':
            pop_value()
            if char == '"':
                state = 'string'
                str_start = index + 1
            elif char == '}':
                current_value = stack.pop() if stack else {}
                if stack:
                    state = 'object_value'
                else:
                    state = 'init'
            else:
                raise ValueError("Expected string key or '}' in object")

        elif state == 'object_value':
            if char == ':':
                index += 1
                state = 'init'
            elif char == '}':
                current_value = stack.pop() if stack else {}
                state = 'init'

        elif state == 'array':
            stack[-1].append(current_value)
            current_value = None
            if char == ']':
                current_value = stack.pop()
                state = 'init'

        index += 1

    if state == 'init' and current_value is not None:
        return current_value
    raise ValueError("Incomplete JSON or unexpected end of input.")

